  const type=Object.hasOwn(VEHICLE_TYPES,r.type)?r.type:(r.type===undefined&&!cleanDims(r.dims)?hintType(VEHICLE_HINTS,name):null);
  if(type)return {id,name,kind,type,size:vehicleStowSize(VEHICLE_TYPES[type].dims),count};
