  if(r.kind==='vehicle'){const q=stowed.get(r.id);fit=q?.embarked??0;return {...r,embarked:fit,unembarked:r.count-fit,loaded:q?.loaded||0,stowed:q?.stowed||0,landable:!!q?.landable,tooLarge:!!q?.tooLarge,dims:q?.dims||groundDims(r)};}
