  if(r.kind==='ship'&&Array.isArray(r.dims)&&r.dims.length===3&&r.dims.every(v=>Number.isFinite(v)&&v>0)){const dims=r.dims.map(v=>Math.round(clamp(v,1,DESIGN_LIMITS.length)*10)/10),ref=typeof r.ref==='string'?r.ref.replace(/[\u0000-\u001f\u007f]/g,'').slice(0,80):'';const design=cleanDesignCraft(r.design);return {id,name,kind:'ship',ref,dims,size:shipStowSize(dims),count,...grouping,...(design?{design}:{})};}
  // v20 an aircraft type (or a custom box); old size-only rows take the type their name names.
