// v24 Interior rooms keep their height within the hull's depth at their station (old frame -> measured frame).
// Interior rooms keep their place in the hull's depth: y in the source model's depth (ob..ot) maps onto the wedge's
// keel and ridge at x (v24: the flat wedge replaced the measured stations the frame's own new columns describe).
let EXECUTOR_WEDGE_HULL=null;
// v24 The wedge's depth at (x, z): the dorsal face above and the ventral face below that point.
function executorWedgeSpan(x,z){EXECUTOR_WEDGE_HULL||={...JSON.parse(JSON.stringify(EXECUTOR_BLUEPRINT.hull)),stations:EXECUTOR_WEDGE_STATIONS.map(r=>r.slice())};const q=sectionBase(EXECUTOR_WEDGE_HULL,x),P=q.poly,a=Math.abs(z),at=(p0,p1)=>p0[1]+(p1[1]-p0[1])*clamp((a-p0[0])/Math.max(1e-9,p1[0]-p0[0]),0,1);
 if(a>q.hw)return {bot:q.ybot,top:q.ybot};const bot=a<=P[1][0]?P[1][1]:at(P[1],P[2]),top=a<=P[4][0]?P[4][1]:at(P[4],P[3]);return {bot,top};}
// A sphere (or a vertical cylinder of that radius) of radius r centred at (x, z) at mid-depth, inside the wedge across
// its whole width: the depth is the narrowest over z−r..z+r.
function executorMidY(x,z,r=0){let bot=-Infinity,top=Infinity;for(const dz of [-r,-r/2,0,r/2,r])for(const dx of [-r,0,r]){const q=executorWedgeSpan(x+dx,z+dz);bot=Math.max(bot,q.bot);top=Math.min(top,q.top);}return (bot+top)/2;}
function executorY(x,y){const F=EXECUTOR_BLUEPRINT.interiorFrame,i=Math.max(0,Math.min(F.length-2,Math.floor(x/500))),t=clamp((x-F[i][0])/500,0,1),g=k=>F[i][k]+(F[i+1][k]-F[i][k])*t,ob=g(1),ot=g(2);EXECUTOR_WEDGE_HULL||={...JSON.parse(JSON.stringify(EXECUTOR_BLUEPRINT.hull)),stations:EXECUTOR_WEDGE_STATIONS.map(r=>r.slice())};const q=sectionBase(EXECUTOR_WEDGE_HULL,x),nb=q.ybot,nt=q.ytop;return nb+(y-ob)*(nt-nb)/Math.max(1,ot-ob);}
