function craftRemodelDesign(key){
 const id=CRAFT_REMODEL_KEYS[key];if(typeof CRAFT_REMODEL!=='object'||!CRAFT_REMODEL?.[id])throw new Error(key+': 航空機のリモデル設計がありません');
 const ship=deserialize(JSON.parse(JSON.stringify(CRAFT_REMODEL[id])));ship.reference=key;ship._craftInteriorRefit=true;ship._craftRemodel=true;
 // 2026-11-27 (user「ノズル部品にしたら、設計の 12 個の構造物（4 門 × 3）を取り除いて部品に置き換える」): the X-wing's nozzle structures give way to the
 // tracking nozzle on its four guns (CRAFT_TRACK_NOZZLE). The structures are found by their labels in the user's design; nothing else of it changes.
 if(id==='xwing'){const gone=new Set(ship.parts.filter(p=>p.k==='struct'&&CRAFT_TRACK_NOZZLE_LABEL.test(p.label||'')).map(p=>p.id));if(gone.size!==12||ship.fits.filter(f=>f.nozzle==='track').length!==4)throw new Error(key+': 追尾ノズルの構造物が 12 個（4 門 × 3）ではありません（'+gone.size+'）');
  ship.parts=ship.parts.filter(p=>!gone.has(p.id));for(const p of ship.parts)if(gone.has(p.tw))delete p.tw;if(Array.isArray(ship.links))ship.links=ship.links.filter(l=>!gone.has(+String(l.from).slice(1))&&!gone.has(+String(l.to).slice(1)));if(Array.isArray(ship.groups))for(const g of ship.groups)if(Array.isArray(g.parts))g.parts=g.parts.filter(i=>!gone.has(i));for(const p of ship.parts)if(Array.isArray(p.wing?.members?.parts))p.wing.members.parts=p.wing.members.parts.filter(i=>!gone.has(i))/* 2026-11-27 (reference-fidelity review) and from the S-foils' member lists */;syncCompartments(ship);}
 // 2026-11-27 (user「TIEアヴェンジャーの翼部レーザーの発射速度は全部1秒3発にして」): the sixteen lasers along the wings' leading edges fire three shots a
 // second (the design had one). They are found by their mounts (the leading-edge gun boxes and edge spars); the guns on the hubs keep their own rate.
 if(id==='tie_avenger'){const host=new Map(ship.parts.map(p=>[p.id,p])),wing=ship.fits.filter(f=>f.k==='claser'&&/前縁|縁桁/.test(host.get(f.host)?.label||''));if(wing.length!==16)throw new Error(key+': 翼のレーザーが 16 門ではありません（'+wing.length+'）');for(const f of wing)f.rateHz=3;const heavy=ship.fits.filter(f=>f.k==='claser'&&/多角形ハブ/.test(host.get(f.host)?.label||''));if(heavy.length!==2)throw new Error(key+': ハブの重レーザーが 2 門ではありません（'+heavy.length+'）');for(const f of heavy)f.rateHz=2/* 2026-11-27 user「重レーザーは毎秒2発で」: the two 0.15 m guns on the outer hubs (were 4 a second); the two under the nose keep 4 */;}
 return ship;
}
