const LUC_AIR=[{id:'air-1',name:'ヴァルチャー級ドロイド・スターファイター',type:'vulture',count:1500},{id:'air-2',name:'C-9979 上陸艇',type:'c9979',count:50}];
const LUC_GROUND=[{id:'ground-1',name:'B1バトル・ドロイド（停止保管）',kind:'droids',count:139000},{id:'ground-2',name:'MTT 大型兵員輸送車',kind:'vehicle',type:'mtt',count:550},{id:'ground-3',name:'AAT 装甲強襲戦車',kind:'vehicle',type:'aat',count:6250}];
// v19 Separatist livery (CIS_PAINT): blue-grey with Separatist blue markings.
const LUC_GREY=CIS_PAINT.grey,LUC_PANEL=CIS_PAINT.panel,LUC_STEEL=CIS_PAINT.steel,LUC_DARK=CIS_PAINT.dark;
function lucrehulkBuild(opt={}){
 const D=LUCR,DX=-1289.3,X=v=>v+DX,R=D.sphere.R,L=2*R;
 // The base hull is the core ship: the sphere measured from the supplied
 // Lucre_Combined_HD.stl (v24), centred 413 m above the frame's floor.
 // Everything else, the C-ring, aft block, arms, claws and towers, is structure.
 const st=[];for(let i=0;i<=24;i++){const t=(1-Math.cos(Math.PI*i/24))/2,r=Math.max(.005,Math.sqrt(Math.max(0,1-(2*t-1)**2)));st.push([+t.toFixed(5),+r.toFixed(4),+r.toFixed(4),+(413/L-.5).toFixed(4)]);}
 const s=newShip({L,W:L,H:L,sec:'ellipse',plan:'ellipse',bowW:1,bowH:1,stern:1,bowFree:true,stations:st},opt.freighter?'LH-3210 型ルクレハルク級貨物船':'ルクレハルク級');
 s.hull.core=true;s.shipClass='battlecruiser';
 s._building=true;s.reference='lucrehulk';s.paint='cis';s.lights='warm';s.detail=1;s.armor={hull:.46,cit:.4};s.shieldTarget=1;
 const k=shipKit(s),part=(kind,label,c,d,o={})=>placePart(s,kind,c,d,{label,...o});
 const loft=(name,label,paint,o={},mirror=false)=>k.loftX(label,D.loft[name],{paint,corner:.12,...o},mirror);
 const col=(label,x,z,y0,y1,w,paint,o={},mirror=false)=>k.box(label,[x-w/2,y0,z-w/2],[x+w/2,y1,z+w/2],{paint,corner:.2,...o},mirror);
 const dish=(label,c,d,t,paint,mirror=false)=>k.ellipsoid(label,c,[t,d,d],{paint},mirror);
 // The ring, arms, spine and aft block are a converted freighter's construction. They were light structures (a quarter
 // of the mass and strength) until 2026-11-14; light structures are abolished and these are ordinary structures now.
 // The ring: outer radius 1,403 m about the core axis, inner radius ratio 0.535,
 // 428 m deep, open ±25° at the bow.
 // v24 The C-ring and the aft block with its spine and towers are stacked plan
 // contours of the supplied Lucre_Combined_HD.stl (outline slabs cut at the
 // middle of each height band); every other solid of it is a measured loft.
 buildMeasuredSolids(s,k,D.parts,{L:3170,paint:LUC_PANEL,roundPaint:LUC_STEEL,nextId:40,slabs:[...D.ringSlabs.map(q=>({...q,label:'環状船体（C字リング）',paint:LUC_GREY})),...D.slabs.map(q=>({...q,label:'艦尾ブロック・脊柱・塔'}))]});
 // ---- forward arms: three hangar zones a side, portals on the inner faces facing the gap ----
 const docks=[];
 for(const [x,zone] of [[2650,'外側格納庫（第1区画）'],[2520,'中間格納庫（第2区画）'],[2390,'内側格納庫（第3区画）']])for(const sg of [1,-1]){
  const d=part('hangar',(sg>0?'右舷アーム ':'左舷アーム ')+zone+'・主格納庫口',[X(x),418,sg*300],30,{room:[100,200,400],airRole:'mixed'});
  openBay(s,d,sg>0?'port':'stbd','open');docks.push(d);}
 if(opt.stage==='dock'){delete s._building;return s;}
 // ---- core ship: centersphere reactor and power generator assemblies in the lower half ----
 const r=part('gen','コア中央球反応炉・発電機集合体',[X(1609),290,0],240);
 // ---- aft block: port and starboard main reactors; the drive thrust chambers draw on the core plant ----
 for(const sg of [1,-1])part('aux',sg>0?'右舷主反応炉（艦尾ブロック）':'左舷主反応炉（艦尾ブロック）',[X(640),470,sg*420],150);
 const eo=equipmentOptions('exposedTurbine');
 for(const [z,rr] of [[-311,r],[0,r],[311,r]]){const d=136,nl=engineBaseline('exposed',d,'nozzleLength'),len=engineBaseline('exposed',d,'length')*1.5;const p=placePart(s,'engine',[X(nl/2),409,z],d,{...eo,label:z?'舷側主推進機関':'中央主推進機関',d,reactor:rr.id,dir:[-1,0,0],engineLength:len},false);resizeEngine(p,d,len);}
 // ---- deflector shield generators under the housing; hyperdrive; inertial units; fuel ----
 for(const sg of [-1,1])part('shield','偏向シールド発生器',[X(960),500,sg*70],80);
 part('hyper','主ハイパードライブ',[X(520),565,0],73.5,{length:180});
 for(const sg of [-1,1])part('inertial','慣性補償装置',[X(1250),418,sg*1080],170,{length:160,dir:[1,0,0]});
 for(const sg of [-1,1])part('fuel','パイロット炉燃料タンク',[X(1611),418,sg*1250],70,{length:200,dir:[0,1,0]});
 // ---- core ship interior: droid control computer core, monitoring stations, repulsorlifts ----
 part('command','ドロイド制御コンピューター・コア',[X(1609),470,0],30,{room:[90,90,70]});
 for(const sg of [-1,1])part('command','制御コンピューター・コア配電監視ステーション',[X(1609),470,sg*120],30,{room:[60,50,40]});
 if(opt.stage==='machinery'){delete s._building;return s;}
 // Heavy guns keep their charging plant wholly inside the envelope and clear of
 // machinery: the plant is pushed deeper until all its corners are enclosed.
 let solidList=null;
 const plantFits=f=>{const q=exampleSeatRoom(f);if(!q)return true;const depth=12,side=Math.sqrt(q.targetVolume/depth),up=fitUp(f),fr=frameAxis(up);solidList=solidList||allOccupied(s).map(p=>({p,b:partAABB(p)}));
  for(const cd of [10,13,16,20,24,28,33,38,44]){const c=sub(f.p,mul(up,cd+(f.mountOffset||0)));let ok=true;
   for(const a of [-.5,0,.5])for(const b of [-.5,0,.5])for(const e of [-.5,0,.5]){const pt=add(c,add(mul(up,a*depth),add(mul(fr.v,b*side),mul(fr.w,e*side))));if(!insideOriginalEnvelope(s,pt)||solidList.some(o=>pt.every((v,i)=>v>=o.b[i]&&v<=o.b[i+3])&&inPart(o.p,pt))){ok=false;break;}}
   if(ok){f.chargeDepth=cd;return true;}}return false;};
 // One fitting cast onto the outermost surface along its axis. Armour plates take
 // no fittings, so a probe that lands on a plate (or finds no surface) is refused.
 const tryMount=(kind,p,axis,zone,o={})=>{const f={id:s.nextId++,k:kind,p:presetStationPoint(s,kind,p,axis,o),a:axis,ped:0,base:0,low:0,float:false,batteryZone:zone,...o};mountFit(s,f);const why=f._onPlate?'plate':f.float?'float':!plantFits(f)?'plant':'';if(opt.dbg)opt.dbg.push([kind,zone,p.map(Math.round).join(','),why||'ok',f.p.map(Math.round).join(',')]);if(why){s.nextId--;return null;}return f;};
 const clearOf=(f,list)=>list.every(g=>Math.hypot(f.p[0]-g.p[0],f.p[1]-g.p[1],f.p[2]-g.p[2])>=((FITS[f.k]?.fm||10)+(FITS[g.k]?.fm||10))*.5+2);
 // n fittings over candidate stations: dorsal ('top') and ventral ('bottom') rows
 // take |z| offsets and mount as mirrored pairs (0 = centreline); 'beam' rows take
 // heights and mount one a side. Stations on plates or crowding others are skipped.
 const spread=(kind,n,mode,zone,xs,offs,o={})=>{let got=0;
  for(const off of offs)for(const x of xs){if(got>=n)break;
   const ps=mode==='beam'?[[[x,off,400],4],[[x,off,-400],5]]:(off?[1,-1]:[1]).map(sg=>[[x,0,sg*off],mode==='top'?2:3]);
   if(got+ps.length>n)continue;const fs=[];
   for(const [p,a] of ps){const f=tryMount(kind,p,a,zone+(ps.length>1?(p[2]>0?'-stbd':'-port'):''),o);if(!f||!clearOf(f,s.fits.concat(fs)))break;fs.push(f);}
   if(fs.length<ps.length)continue;s.fits.push(...fs);got+=fs.length;}
  if(got<n)throw new Error('作例の砲座が不足しています: '+kind+' '+zone+' '+got+'/'+n);};
 const range=(a,b,st)=>{const r=[];for(let x=a;x<=b+1e-6;x+=st)r.push(x);return r;};
 // Pods seat on the first wall hit among a few probe heights.
 const podAt=(kind,host,o,dir)=>{let err='取付面がありません';for(const dy of [0,-4,4,-8,8,-12,12,-16,16])for(const dz of [0,-6,6,-12,12]){const q0=[o[0],o[1]+dy,o[2]+(dir[2]?0:dz)];const hit=host?rayPart(q0,dir,host):rayStructs(s,sub(q0,mul(dir,800)),dir);if(!hit)continue;const r=placeFit(s,kind,hit.p,hit.n,0,false);if(r.fit){r.fit.commandDepth=7;r.fit.commandHeight=5;return r.fit;}err=r.err;}throw new Error('艦橋ポッド '+kind+': '+err);};
 // v24 The measured structures differ from the hand-built ones: try the authored point first, then step along the ship.
 const pod=(kind,host,o,dir)=>{let last;for(const dx of [0,-30,30,-60,60,-100,100,-150,150,-200,200])try{return podAt(kind,host,[o[0]+dx,o[1],o[2]],dir);}catch(e){last=e;}throw last;};

 const claw=s.parts.find(p=>p.label==='主ドッキング・クロー'&&p.c[2]>0),btower=s.parts.find(p=>p.label==='コアシップ管制ブリッジ塔');
 pod('podBridge',btower,[X(1609),750,60],[0,0,-1]);
 pod('podAir',claw,[X(2800),418,-200],[0,0,1]);
 syncAviationSurfaces(s);s._lockedCache=cache(s);
 try{withFrozenStructures(()=>{
  // Forty-two equatorial stations retain their mirrored arrangement: each
  // group seats a pair of CIS rapid quads and four Mon Calamari 34 TT balls.
  for(let g=0;g<7;g++){const a0=42+g*20,xs=[a0-4,a0,a0+4].map(a=>X(1611)+1403*Math.cos(a*Math.PI/180));spread('quad1Rapid',2,'beam','midline-rapid-'+(g+1),xs,[418,430,406,442,394]);spread('monCal34',4,'beam','midline-ball-'+(g+1),xs,[418,430,406,442,394]);}
  // transmitter platform defence artillery
  spread('monCalPD',4,'top','platform-defence',range(X(570),X(850),30),[130,100]);
  // main tractor beam generators and multiple tractor beam projectors on the forward arms
  spread('trc',6,'beam','arm-tractor',range(X(2860),X(3060),20),[470,430,510,390]);
 });}finally{delete s._lockedCache;}
 // LH-3210 freighter (opt.freighter): the same hull unarmed — the quad laser batteries and the defence artillery come
 // off (the tractor beams stay for cargo handling) and the volume their mounts took (footprint × height of each fit,
 // fitSpec) goes back to the holds below.
 let freed=0;if(opt.freighter){const gone=s.fits.filter(f=>['quad1Rapid','monCal34','monCalPD'].includes(f.k));for(const f of gone){const d=fitSpec(f);freed+=Math.max(0,(d.fm||0)*(d.wm||0)*(d.hm||0));}s.fits=s.fits.filter(f=>!gone.includes(f));}
 if(opt.stage==='fitted'){delete s._building;return s;}

 if(opt.stage==='shape'){delete s._building;return s;}
 for(const [kind,label,c,size,role,mirror] of D.rooms||[]){const o={room:size};if(typeof role==='string')o.airRole=role;placePart(s,kind,c,30,{label,...o},mirror===1||role===1);}
 // v20 The landing ships ride in the ring: C-9979 decks stacked fourteen high, with doors in the ring's underside.
 if(opt.freighter){
  // The freighter's ring holds cargo where the battleship's landing-ship decks are, each a quarter of the freed volume longer.
  for(const [x,n] of [[322,'第1'],[552,'第2']])for(const sg of [1,-1])part('cargo',(sg>0?'右舷':'左舷')+'環状船体 貨物倉（'+n+'区画）',[x,402.5,sg*1005],30,{room:[216+freed/4/(400*395),400,395]});
  s.airWings=[];s.groundForces=normalizeGroundForces([]);
 }else{
 for(const [x,n] of [[322,'第1'],[552,'第2']])for(const sg of [1,-1]){const bay=part('hangar',(sg>0?'右舷':'左舷')+'環状船体 C-9979 上陸艇格納甲板（'+n+'区画）',[x,402.5,sg*1005],30,{room:[216,400,395],airRole:'storage'});openBay(s,bay,'bottom','open');}
 s.airWings=LUC_AIR.map(r=>({...r}));s.groundForces=normalizeGroundForces(LUC_GROUND);
 }
 // 2026-11-14 user decision: the ring of this converted freighter is mostly holds. Cargo holds follow the ring (turned
 // to its tangent) in the free arcs between the bow opening, the landing-ship decks, the inertial units and the aft
 // block's rooms: mid radius 1,077 m about the core axis, 560 m of the ring's 653 m radial depth, 395 m high.
 {const cx=X(1609),rm=1077;for(const [a,t,n] of [[120.5,220,'後部']])/* the forward arcs are taken by the arms' fighter racks */for(const sg of [1,-1]){const r=a*Math.PI/180;part('cargo',(sg>0?'右舷':'左舷')+'環状船体 貨物倉（'+n+'）',[cx+rm*Math.cos(r),402.5,sg*rm*Math.sin(r)],30,{room:[t,560,395],yaw:sg*(a-90)});}}
 delete s._building;adoptEquipment(s,true);remount(s);calibrateReferenceRatings(s);syncCompartments(s);
 return s;

}
registerShipExample({
 key:'lucrehulk',name:'ルクレハルク級',side:'独立星系連合',role:'環状母艦（ドロイド司令船）',length:3170,
 title:'Lucrehulk',author:'Professor E12^2',authorUrl:'https://sketchfab.com/profanity2009',
 source:'https://sketchfab.com/3d-models/lucrehulk-8bb11e0ad31e4b23b1783e10242c5115',license:'CC BY 4.0',
 credit:'This work is based on "Lucrehulk" (https://sketchfab.com/3d-models/lucrehulk-8bb11e0ad31e4b23b1783e10242c5115) by Professor E12^2 (https://sketchfab.com/profanity2009) licensed under CC-BY-4.0 (http://creativecommons.org/licenses/by/4.0/)',
 note:'基本船体は直径 640 m の球形のコアシップ（モデルから実測、公式は約 696 m）で、C 字形の環状船体・艦尾ブロック・前部アームとドッキング・クロー・各種の塔はすべて構造物（全長 3,170 m）。コアシップの中心にドロイド制御コンピューター・コアと配電監視ステーション、下半分にコア中央球反応炉・発電機集合体、底部に着陸用リパルサーリフト、頂部に管制ブリッジ塔。艦尾背部の信号送信プラットフォームに予備制御信号送信塔・送信塔アンテナ・主／補助センサー・レクテナ・高エネルギー送信塔と防衛砲、前部アームにドロイド信号受信ステーション・前部管制塔・予備センサー・レクテナ・主トラクター・ビーム発生器とドッキング用トラクター・ビーム収納部、環状船体上部に偏向シールド発生器ハウジングと投射器。各アームの内側面に外側・中間・内側の 3 区画の主格納庫口、ドロイド・スターファイターのラック、地上部隊の補給物資庫、格納甲板床下の予備部品庫、貨物ベイ、大規模弾薬庫。環状船体の左右に C-9979 上陸艇の格納甲板 4 区画（14 段積み、下面に扉）。艦尾ブロックに左右の主反応炉と主推進機関スラスト・チャンバー。兵装は環状船体の赤道に沿った34TT単装球状ターボレーザー28基とCIS向け1TT×4速射砲14基（計42基）、送信プラットフォームの球状3連装点防御砲4基、トラクター・ビーム6基。ヴァルチャー 1,500 機、C-9979 上陸艇 50 隻、B1 バトル・ドロイド 13 万 9,000 体、MTT 550 両、AAT 6,250 両。MTT と AAT の大半は上陸艇 1 隻に AAT 114 両・MTT 11 両ずつ積んだまま格納し、1 回の降下で上陸艇 50 隻と MTT がドロイド全軍を降ろせる。ハイパードライブ・クラス 2、加速約 1,300 G はゲーム上の設定値。Sketchfab の 3D モデル（Professor E12^2 作、CC BY 4.0）を実測。',
 airWings:LUC_AIR,groundForces:LUC_GROUND,
 build:lucrehulkBuild
});
