function buildMandatorReference(){
 const design=JSON.parse(JSON.stringify(MAN2_EXTERIOR)),I=JSON.parse(JSON.stringify(MAN2_INTERIOR)),M=MAN2_MOUNTS,hullId=design.parts.find(p=>p.form==='hull'&&p.primaryHull!==false)?.id;
 design.parts.push(...I.parts);
 // One engine in each nozzle bell. The bells are the user's structures (four quarter shells, a mounting ring and a back
 // face each); the engine keeps the identity of the previous example's engine at that place (MAN2_INTERIOR.engines: id, y, z).
 for(let n=1;n<=11;n++){const tag=String(n).padStart(2,'0'),ps=design.parts.filter(p=>new RegExp('ノズル '+tag+'｜').test(p.label||'')),back=ps.find(p=>/奥面/.test(p.label)),shells=ps.filter(p=>/開口外殻/.test(p.label));
  if(!back||shells.length!==4)throw new Error('Mandator II: ノズル外装 '+tag+' が見つかりません');
  const x=back.c[0]-back.s[0]/2,exit=Math.min(...shells.map(p=>p.c[0]-p.s[0]/2)),d=(shells[0].s[1]*2-2*(shells[0].shellThick||5))*.9,L=Math.min(d*.9,(x-exit)*.8),was=I.engines.reduce((m,e)=>Math.hypot(e[1]-back.c[1],e[2]-back.c[2])<Math.hypot(m[1]-back.c[1],m[2]-back.c[2])?e:m);
  if(design.parts.some(p=>p.id===was[0]))throw new Error('Mandator II: ノズル外装 '+tag+' の機関が重複しています');
  design.parts.push({id:was[0],k:'engine',c:[x-L/2,back.c[1],back.c[2]],d,dir:[-1,0,0],reactor:I.parts.find(p=>p.k==='gen').id,label:(/主ノズル/.test(back.label)?'主機関 ':'補助機関 ')+tag,engineLength:L,nozzleLength:L});}
 design.hatches=I.hatches.map(h=>({...h,hullOwner:hullId}));
 design.nextId=Math.max(design.nextId||1,...design.parts.map(p=>p.id+1),...design.hatches.map(h=>h.id+1));design.armor=I.armor;design.shieldTarget=I.shieldTarget;design.autoHabitation=I.autoHabitation;design.name=I.name;
 const s=deserialize(design);s.reference='mandator2';s._building=true;
 // The plant and the shields are sized to the reference figures from their real volumes.
 const ref=SHIP_REFERENCE.mandator2,main=s.parts.find(p=>p.k==='gen'),aux=s.parts.find(p=>p.k==='aux'),reactorVolume=ref.power/REACTOR_POWER_DENSITY-partVolume(main);
 aux.room=[1000,430,reactorVolume/(1000*430)];aux.corner=0;aux.autoFit=true;aux.customEquipment=true;delete aux.equipmentId;aux.label='分散副反応炉区画（標準出力密度）';
 const shields=s.parts.filter(p=>p.k==='shield'||p.k==='localShield'),shieldVolume=shields.reduce((n,p)=>n+partVolume(p),0),shieldScale=Math.cbrt(ref.shieldLoad/(SHIELD_ENERGY_DENSITY*shieldVolume));
 for(const p of shields){p.d*=shieldScale;p.customEquipment=true;delete p.equipmentId;p.shieldDissipationW=ref.shieldDissipationW/shields.length;}
 // Room tessellation is Float32: solve the reactor room's real retained volume.
 const sizeReactor=()=>{syncCompartments(s);for(let i=0;i<16;i++){const ratio=reactorVolume/Math.max(1,partVolume(aux));if(Math.abs(ratio-1)<2e-8)break;aux.room[2]*=ratio;syncCompartments(s);}};sizeReactor();
 const oldLock=s._lockedCache;s._lockedCache=cache(s);s._rayLock={env:null,tris:new Map()};
 const count={},fail=[];
 // A mount is seated on the first surface under its measured position, looking along its measured normal.
 const put=(zone,k,pos,n,opt={})=>{const rise=opt.rise||400,h=rayEnv(s,add(pos,mul(n,rise)),mul(n,-1),{maxT:rise*2.25,structOnly:true});if(!h){fail.push(zone+' '+pos.map(Math.round)+'：面がありません');return;}
  /* user instruction 2026-11-21「マンデイターについて、面に合わせて傾けて配置するようにして」: opt.surface seats the gun on the face it meets, tilted to it */
  /* the face met must be the mount's own face: a point-defence pair is seated at the midpoint of its two bases, and where that midpoint
     falls on a side wall (79° from the bases, reference-fidelity review 2026-11-21) the bases' measured normal is kept */
  const face=opt.surface&&h.n&&dot(norm(h.n),norm(n))>=Math.cos(Math.PI/4)?h.n:n;
  const before=s.fits.length,r=placeFit(s,k,h.p,face,opt.ped??0,!!opt.mirror,opt.surface?{...(opt.o||{}),mountMode:'auto',tilt:true}:opt.o||{});if(r?.err){s.fits.splice(before);fail.push(zone+' '+pos.map(Math.round)+'：'+r.err);return;}
  for(const f of s.fits.slice(before)){f.batteryZone=zone+(f.p[2]>1?'-stbd':f.p[2]<-1?'-port':'-centre');count[zone]=(count[zone]||0)+1;}};
 try{
  for(const p of M.utl)put('main-utl','utl',p,[0,1,0],{mirror:p[2]>1,surface:true});
  for(const p of M.quad175)put('secondary-quad175','quad175',p,[0,1,0],{mirror:p[2]>1,surface:true});
  for(const q of M.ion)put('ion-ball','ball175QuadIon',q.slice(0,3),norm(q.slice(3)),{mirror:true,o:{mountMode:'auto',tilt:true,assetPitch:90}});
  for(const q of M.ventral)put('ventral-'+q[0],q[0],[q[1],q[2]+60,q[3]],[0,-1,0],{mirror:true,ped:q[4],surface:true});
  // Point defence: the source model's small bases in pairs, one mount on each pair (user decision 2026-11-19「点防御は2個1組で」).
  // The nearest bases are paired first; a base left over on the centreline pairs with its mirror image; other leftovers stay empty.
  {const bases=M.pd,used=new Set(),cand=[];for(let i=0;i<bases.length;i++)for(let j=i+1;j<bases.length;j++){if(dot(bases[i].slice(3),bases[j].slice(3))<.9)continue;const d=len(sub(bases[i].slice(0,3),bases[j].slice(0,3)));if(d<=260)cand.push([d,i,j]);}cand.sort((a,b)=>a[0]-b[0]||a[1]-b[1]||a[2]-b[2]);
   for(const [d,i,j] of cand){if(used.has(i)||used.has(j))continue;used.add(i);used.add(j);const n=norm(bases[i].slice(3));put('pd','pd',mul(add(bases[i].slice(0,3),bases[j].slice(0,3)),.5),n,{mirror:true,rise:70,ped:.15,surface:true});}
   bases.forEach((b,i)=>{if(!used.has(i)&&Math.abs(b[2])<100){used.add(i);put('pd','pd',[b[0],b[1],0],[0,b[4]<0?-1:1,0],{rise:70,ped:.15,surface:true});}});}
  // Heavy launchers (6 by 2 tubes, embedded, the tubes' rows along the hull) on the rack blocks of the side trench. The
  // source model has four racks a side; the user's exterior has three blocks a side, and only those carry a rack.
  for(const blk of s.parts.filter(p=>/トレンチ隔壁・外板・右舷/.test(p.label||'')&&Math.abs(p.s[0]-90)<1.5&&Math.abs(p.s[2]-32)<1.5)){let h=null;
   const rack=(p,n)=>({k:'shipMsl',p,a:0,ped:0,n:n.slice(),tilt:n.slice(),frameForward:[0,1,0],launcherCols:6,launcherRows:2,launchYaw:0,launcherEmbedded:true,launcherHeavy:true,round:'msl'});
   for(const dy of [0,-3,3,-6,6]){const g=rayEnv(s,[blk.c[0],blk.c[1]+dy,3000],[0,0,-1],{maxT:6000,structOnly:true});if(g&&g.part===blk&&!mountFit(s,{id:-7,...rack(g.p.slice(),g.n)}).float){h=g;break;}}
   if(!h){fail.push('launcher '+blk.c.map(Math.round)+'：ラックを取り付けられません');continue;}
   for(const sgn of [1,-1]){const f=mountFit(s,{id:nid(s),...rack([h.p[0],h.p[1],h.p[2]*sgn],[h.n[0],h.n[1],h.n[2]*sgn]),batteryZone:'launcher'+(sgn>0?'-stbd':'-port')});if(f.float){fail.push('launcher '+f.p.map(Math.round)+'：浮いています');continue;}s.fits.push(f);count.launcher=(count.launcher||0)+1;}}
 }finally{if(oldLock)s._lockedCache=oldLock;else delete s._lockedCache;delete s._rayLock;delete s._building;}
 if(fail.length)throw new Error('Mandator II: 兵装を配置できません：'+fail.slice(0,6).join('／'));
 for(const [zone,n] of Object.entries(M.expect))if((count[zone]||0)!==n)throw new Error('Mandator II: '+zone+' の数が合いません（'+(count[zone]||0)+'/'+n+'）');
 const volley=s.fits.reduce((n,f)=>n+(f.float?0:(FITS[f.k]?.tt||0)+(FITS[f.k]?.ion||0)),0);
 if(Math.abs(volley/ref.volleyTT-1)>.035)throw new Error('Mandator II: 斉射合計が指定値の±3.5%に収まりません（'+Math.round(volley)+' TT）');
 sizeReactor();
 const actualPower=s.parts.filter(isReactor).reduce((n,p)=>n+ratedReactorPower(p),0),actualShield=shields.reduce((n,p)=>n+shieldLoad(p),0);
 if(Math.abs(actualPower/ref.power-1)>1e-7)throw new Error('Mandator II: 反応炉の実区画容積が指定出力に不足しています');
 if(Math.abs(actualShield/ref.shieldLoad-1)>1e-7)throw new Error('Mandator II: シールド発生器の実容積が指定容量に不足しています');
 return s;
}
registerShipExample({
 key:'mandator2',name:MAN2_INTERIOR.name,side:'銀河共和国',role:'艦隊旗艦・ドレッドノート',length:8000,
 title:'Mandator II-class Star Dreadnaught',credit:'ユーザーの外装設計（2026-11-21 提供の 2 つ目のモデル）。形状の元は MandatorIIClassDreadnaught.STL（ユーザー提供。作者・ライセンスの表記なし）',author:'ユーザー（形状の元は作者不明の STL）',source:'ユーザーの設計ファイル（assets/source/mandator2-user-exterior/）',license:'不明（元の STL に出典・ライセンスの記載なし）',
 note:'ユーザーの外装設計を土台にした作例（2026-11-21 に 2 つ目のモデルで作り直し）。公式の寸法は無く、ファン設定で多い全長 8 km。短剣形の主船体、舷側のトレンチ、段状の城郭と艦橋塔、腹部の二つの反応炉ドーム、艦尾の 11 基のノズル外装はユーザーが設計画面で組んだもの。兵装は原本の STL から測った搭載位置に載せる：八角形の台 47 か所に 720TT 連装、四角い窪み 24 か所に 175TT 四連装、箱に埋まった球 16 か所に 175TT 四連装イオンのボールターレット、小さな台 2 個 1 組に点防御、舷側トレンチのラック台 6 か所に大型ランチャー（6×2 発）。下面には原本に搭載位置が無いため、従来の作例と同じ場所に 720TT 連装 14 基と 175TT 四連装 24 基を置く。機関は各ノズルに 1 基で、本体はノズルの直前から主反応炉の方向へ引き延ばして置き、軸で繋ぐ。ハイパードライブは艦尾中央の張り出し甲板室、反応物の設備は主反応炉の前、熱エネルギー変換装置は機関の列の間に置く。ハイパードライブ（クラス2、予備クラス10）と乗員は公式値が無いため想定で、持ち場の大半を自動化装置に任せている。',
 airWings:MAN2_INTERIOR.airWings,groundForces:MAN2_INTERIOR.groundForces,
 build:buildMandatorReference
});
