  const dpK=dpRows.length?dpRows.reduce((n,{m,i})=>n+dpWeight(m)*clamp(u.mods?.[i]??1,0,1)*powerFactor(u,'weapon',i),0)/dpRows.reduce((n,{m})=>n+dpWeight(m),0):1;
