 const at=(i,j)=>add(add(add(o,mul(fr.fw,-sp.fm/2-rl/2)),mul(fr.up,sp.hm/2+j*w)),mul(fr.rt,i*w)),boxOf=c=>{const P=[];for(const a of [-1,1])for(const b of [-1,1])for(const e of [-1,1])P.push(add(add(add(c,mul(fr.fw,a*rl/2)),mul(fr.up,b*w/2)),mul(fr.rt,e*w/2)));return {P,b:[0,1,2].map(k=>Math.min(...P.map(p=>p[k]))).concat([0,1,2].map(k=>Math.max(...P.map(p=>p[k]))))};};
 const hit=(a,b)=>a[0]<b[3]-1e-6&&a[3]>b[0]+1e-6&&a[1]<b[4]-1e-6&&a[4]>b[1]+1e-6&&a[2]<b[5]-1e-6&&a[5]>b[2]+1e-6,rings=(ship?.parts||[]).filter(p=>p.k==='bombBay'&&p.bayRing===true),gear=(ship?.parts||[]).filter(p=>!isShapePart(p)&&!isWing(p)&&p.k!=='solarPanel'&&!rings.includes(p)).map(p=>{try{return partAABB(p);}catch(e){return null;}}).filter(Boolean),ringHit=B=>rings.some(p=>{let b;try{b=partAABB(p);}catch(e){return false;}return hit(B,b)&&!ringBayHollowHoldsBox(p,B);})/* a cell inside a ring bay's hollow is free; one in the ring of bombs is not */;
 const free=(i,j)=>{const c=at(i,j),B=boxOf(c);if(![c,...B.P].every(p=>insideOriginalEnvelope(ship,p)))return null;if(gear.some(g=>hit(B.b,g))||ringHit(B.b)||taken.some(g=>hit(B.b,g)))return null;return {c,b:B.b,i,j};};
 const put=cell=>{cells.push(cell);taken.push(cell.b);};
 {const c=at(0,0),B=boxOf(c);put({c,b:B.b,i:0,j:0,behind:true});}/* straight behind the launcher, always */
 const side=[{d:[-1,0],n:0,open:true},{d:[1,0],n:0,open:true},{d:[0,1],n:0,open:true},{d:[0,-1],n:0,open:true}],opp=[1,0,3,2],step=k=>{const q=side[k];if(!q.open)return false;const cell=free(q.d[0]*(q.n+1),q.d[1]*(q.n+1));if(!cell){/* ★ ours: a side that has no cell yet may start up to three steps out (a launcher standing on a surface has the skin between it and the structure under it); once it has cells, the first step with no room ends it */if(!q.made&&q.n<3){q.n++;return false;}q.open=false;return false;}q.n++;q.made=true;put(cell);return true;};
