  if(f.k==='cpylon'){const m=mirrorP(f.p),pair=ship.fits.find(g=>g!==f&&g.k==='cpylon'&&(g.id===f.tw||len(sub(g.p,m))<.02)),id=pair?Math.min(f.id,pair.id):f.id;add('cpylon:'+id,{fit:'cpylon',mount:'wing'});}
